[918230]={"While in Metamorphosis, increases the armor gained from cloth equipment by 5% and reduces area damage taken by 3%.","While in Metamorphosis, increases the armor gained from cloth equipment by 10% and reduces area damage taken by 6%.","While in Metamorphosis, increases the armor gained from cloth equipment by 15% and reduces area damage taken by 9%."},
[918240]={"Increases the mana restored by Life Tap by 5% without increasing its health cost. Does not reduce its existing health cost.","Increases the mana restored by Life Tap by 10% without increasing its health cost. Does not reduce its existing health cost."},
[918250]={"Reduces Torment's cooldown by 1 sec, to a minimum of 5 sec. Successfully taunting increases your threat generation against that target by 5% for 6 sec.","Reduces Torment's cooldown by 2 sec, to a minimum of 5 sec. Successfully taunting increases your threat generation against that target by 10% for 6 sec.","Reduces Torment's cooldown by 3 sec, to a minimum of 5 sec. Successfully taunting increases your threat generation against that target by 15% for 6 sec."},
[918260]={"Increases your direct and periodic Fire damage by 2% while in Metamorphosis.","Increases your direct and periodic Fire damage by 4% while in Metamorphosis.","Increases your direct and periodic Fire damage by 6% while in Metamorphosis."},
[918270]={"When Drain Life completes at least 3 healing ticks, its third tick additionally heals you for 1% of maximum health. Cannot occur more than once every 10 sec.","When Drain Life completes at least 3 healing ticks, its third tick additionally heals you for 2% of maximum health. Cannot occur more than once every 10 sec.","When Drain Life completes at least 3 healing ticks, its third tick additionally heals you for 3% of maximum health. Cannot occur more than once every 10 sec."},
[918280]={"While in Metamorphosis, increases your Shadow and Fire damage by 1% and threat generation by 3%.","While in Metamorphosis, increases your Shadow and Fire damage by 2% and threat generation by 6%.","While in Metamorphosis, increases your Shadow and Fire damage by 3% and threat generation by 9%.","While in Metamorphosis, increases your Shadow and Fire damage by 4% and threat generation by 12%.","While in Metamorphosis, increases your Shadow and Fire damage by 5% and threat generation by 15%."},
[918290]={"While Void Ward is active, reduces magic damage taken by 2%. Ends when the shield expires or is consumed; does not grant school immunity.","While Void Ward is active, reduces magic damage taken by 4%. Ends when the shield expires or is consumed; does not grant school immunity.","While Void Ward is active, reduces magic damage taken by 6%. Ends when the shield expires or is consumed; does not grant school immunity."},
[918300]={"In Metamorphosis, Demonic Slash grants a nonstacking shield equal to 2% of maximum health for 5 sec; Soul Cleave heals 20% more. Taking magic damage reduces Void Ward's cooldown by 1 sec, at most once every 2 sec. Immolation Aura generates 20% more threat. Demon Leap reduces damage taken by 10% for 3 sec. Surviving damage below 20% health grants Demonic Bastion, reducing damage taken by 20% for 6 sec, once every 90 sec; it cannot prevent the triggering hit from killing you."},
[919000]={"Reduces the Rage cost of Maul, Mangle in Bear Form and Thrash by 1, to a minimum of 5 Rage.","Reduces the Rage cost of Maul, Mangle in Bear Form and Thrash by 2, to a minimum of 5 Rage.","Reduces the Rage cost of Maul, Mangle in Bear Form and Thrash by 3, to a minimum of 5 Rage.","Reduces the Rage cost of Maul, Mangle in Bear Form and Thrash by 4, to a minimum of 5 Rage.","Reduces the Rage cost of Maul, Mangle in Bear Form and Thrash by 5, to a minimum of 5 Rage."},
[919010]={"Increases the armor contribution of cloth and leather equipment in Bear Form by 10%.","Increases the armor contribution of cloth and leather equipment in Bear Form by 20%.","Increases the armor contribution of cloth and leather equipment in Bear Form by 30%."},
[919020]={"Increases Maul and Swipe in Bear Form damage by 10%.","Increases Maul and Swipe in Bear Form damage by 20%."},
[919030]={"Increases your threat generation in Bear Form by 5% and Swipe damage by 3%.","Increases your threat generation in Bear Form by 10% and Swipe damage by 6%.","Increases your threat generation in Bear Form by 15% and Swipe damage by 9%."},
[919040]={"Increases Bash's stun duration by 0.5 sec and reduces its cooldown by 5 sec, to a minimum of 30 sec. Does not bypass stun immunity.","Increases Bash's stun duration by 1 sec and reduces its cooldown by 10 sec, to a minimum of 30 sec. Does not bypass stun immunity."},
[919050]={"Reduces Ironfur's Rage cost by 2, from 20 to 18, and increases its duration by 0.5 sec.","Reduces Ironfur's Rage cost by 4, from 20 to 16, and increases its duration by 1 sec.","Reduces Ironfur's Rage cost by 6, from 20 to 14, and increases its duration by 1.5 sec."},
[919060]={"Increases your dodge chance in Bear Form by 2%. Dodging grants 1 Rage, at most once every 2 sec.","Increases your dodge chance in Bear Form by 4%. Dodging grants 2 Rage, at most once every 2 sec.","Increases your dodge chance in Bear Form by 6%. Dodging grants 3 Rage, at most once every 2 sec."},
[919070]={"Your direct Bear ability critical strikes grant 2 Rage. Applied once per cast regardless of targets; cannot occur more than once every 1 sec.","Your direct Bear ability critical strikes grant 4 Rage. Applied once per cast regardless of targets; cannot occur more than once every 1 sec."},
[919080]={"Increases your expertise in Bear Form by 5. Refunds 40% of a Bear ability's Rage cost when its primary attack is dodged or parried; no refund for a successful attack on another target.","Increases your expertise in Bear Form by 10. Refunds 80% of a Bear ability's Rage cost when its primary attack is dodged or parried; no refund for a successful attack on another target."},
[919090]={"Increases Survival Instincts' duration by 2 sec and reduces its cooldown by 15 sec, to a minimum of 120 sec.","Increases Survival Instincts' duration by 4 sec and reduces its cooldown by 30 sec, to a minimum of 120 sec."},
[919100]={"Increases your Lacerate and Thrash bleed damage by 10%.","Increases your Lacerate and Thrash bleed damage by 20%."},
[919110]={"Reduces Mangle in Bear Form's cooldown by 0.5 sec, to a minimum of 3 sec, and increases its damage by 3%.","Reduces Mangle in Bear Form's cooldown by 1 sec, to a minimum of 3 sec, and increases its damage by 6%.","Reduces Mangle in Bear Form's cooldown by 1.5 sec, to a minimum of 3 sec, and increases its damage by 9%."},
[919120]={"While in Bear Form, reduces your chance to be critically hit by monsters by 2 percentage points and increases all attributes by 1%. Does not reduce critical strike chance from players.","While in Bear Form, reduces your chance to be critically hit by monsters by 4 percentage points and increases all attributes by 2%. Does not reduce critical strike chance from players.","While in Bear Form, reduces your chance to be critically hit by monsters by 6 percentage points and increases all attributes by 3%. Does not reduce critical strike chance from players."},
[919130]={"Reduces all damage taken in Bear Form by 4%. Does not require party members or increase with party size.","Reduces all damage taken in Bear Form by 8%. Does not require party members or increase with party size.","Reduces all damage taken in Bear Form by 12%. Does not require party members or increase with party size."},
[919140]={"Your Maul and Mangle hits reduce the target's movement speed by 10% and melee attack speed by 3% for 12 sec. One nonstacking debuff per target; normal immunity rules apply.","Your Maul and Mangle hits reduce the target's movement speed by 20% and melee attack speed by 6% for 12 sec. One nonstacking debuff per target; normal immunity rules apply.","Your Maul and Mangle hits reduce the target's movement speed by 30% and melee attack speed by 9% for 12 sec. One nonstacking debuff per target; normal immunity rules apply."},
[919150]={"Reduces Feral Charge in Bear Form's cooldown by 2 sec, to a minimum of 8 sec. On arrival, grants 3 Rage once.","Reduces Feral Charge in Bear Form's cooldown by 4 sec, to a minimum of 8 sec. On arrival, grants 6 Rage once."},
[919160]={"Increases your Stamina in Bear Form by 2%.","Increases your Stamina in Bear Form by 4%.","Increases your Stamina in Bear Form by 6%.","Increases your Stamina in Bear Form by 8%.","Increases your Stamina in Bear Form by 10%."},
[919170]={"Maul and Mangle in Bear Form deal 2% more damage to targets affected by your Lacerate or Thrash bleed.","Maul and Mangle in Bear Form deal 4% more damage to targets affected by your Lacerate or Thrash bleed.","Maul and Mangle in Bear Form deal 6% more damage to targets affected by your Lacerate or Thrash bleed.","Maul and Mangle in Bear Form deal 8% more damage to targets affected by your Lacerate or Thrash bleed.","Maul and Mangle in Bear Form deal 10% more damage to targets affected by your Lacerate or Thrash bleed."},
[919180]={"Increases the attack power contribution to each Savage Defense shield by 10% relative to its normal coefficient. Does not increase its duration or permit shields to stack.","Increases the attack power contribution to each Savage Defense shield by 20% relative to its normal coefficient. Does not increase its duration or permit shields to stack.","Increases the attack power contribution to each Savage Defense shield by 30% relative to its normal coefficient. Does not increase its duration or permit shields to stack."},
[919190]={"Ironfur also reduces Physical damage taken by 5% while active. Multiple applications do not stack this damage reduction."},
[919200]={"Your Lacerate and Thrash periodic damage can critically strike, using your melee critical strike chance and a 200% total critical damage multiplier. Periodic critical strikes cannot trigger Primal Fury or Savage Defense."},
[919210]={"Increases Pulverize damage by 5% and its critical strike bonus duration by 1 sec.","Increases Pulverize damage by 10% and its critical strike bonus duration by 2 sec.","Increases Pulverize damage by 15% and its critical strike bonus duration by 3 sec."},
[919220]={"Reduces the Rage cost of Swipe, Lacerate and Pulverize by 1, to a minimum of 5 Rage.","Reduces the Rage cost of Swipe, Lacerate and Pulverize by 2, to a minimum of 5 Rage.","Reduces the Rage cost of Swipe, Lacerate and Pulverize by 3, to a minimum of 5 Rage."},
[919230]={"Your Bear auto attacks have a 10% chance to empower your next Maul within 8 sec. That Maul makes the target's next direct melee hit against you deal 10% less damage. One charge, lasting 6 sec on the target; cannot trigger more than once every 8 sec.","Your Bear auto attacks have a 20% chance to empower your next Maul within 8 sec. That Maul makes the target's next direct melee hit against you deal 20% less damage. One charge, lasting 6 sec on the target; cannot trigger more than once every 8 sec.","Your Bear auto attacks have a 30% chance to empower your next Maul within 8 sec. That Maul makes the target's next direct melee hit against you deal 30% less damage. One charge, lasting 6 sec on the target; cannot trigger more than once every 8 sec."},
[919240]={"Enemies affected by your Thrash bleed deal 2% less Physical damage to you. Does not reduce their damage to allies.","Enemies affected by your Thrash bleed deal 4% less Physical damage to you. Does not reduce their damage to allies.","Enemies affected by your Thrash bleed deal 6% less Physical damage to you. Does not reduce their damage to allies."},
[919250]={"Frenzied Regeneration additionally heals you for 5% of the health damage you took during the 5 sec before activation, capped at 5% of maximum health. Spread evenly over its existing duration; one snapshot per activation, excluding self-inflicted and absorbed damage.","Frenzied Regeneration additionally heals you for 10% of the health damage you took during the 5 sec before activation, capped at 10% of maximum health. Spread evenly over its existing duration; one snapshot per activation, excluding self-inflicted and absorbed damage.","Frenzied Regeneration additionally heals you for 15% of the health damage you took during the 5 sec before activation, capped at 15% of maximum health. Spread evenly over its existing duration; one snapshot per activation, excluding self-inflicted and absorbed damage."},
[919260]={"After Pulverize consumes at least 3 Lacerate stacks, reduces damage taken by 2% for 6 sec. Does not stack or refresh more than once every 3 sec.","After Pulverize consumes at least 3 Lacerate stacks, reduces damage taken by 4% for 6 sec. Does not stack or refresh more than once every 3 sec.","After Pulverize consumes at least 3 Lacerate stacks, reduces damage taken by 6% for 6 sec. Does not stack or refresh more than once every 3 sec."},
[919270]={"Challenging Roar also reduces damage taken by 10% for 6 sec. Uses its normal cooldown; no new taunt immunity bypass and no additional taunt charge."},
[919280]={"Increases healing received in Bear Form by 2% and reduces the duration of stuns on you by 5%. Does not prevent stuns.","Increases healing received in Bear Form by 4% and reduces the duration of stuns on you by 10%. Does not prevent stuns.","Increases healing received in Bear Form by 6% and reduces the duration of stuns on you by 15%. Does not prevent stuns."},
[919290]={"While in Bear Form, increases your attack power by 2% and maximum health by 1%.","While in Bear Form, increases your attack power by 4% and maximum health by 2%.","While in Bear Form, increases your attack power by 6% and maximum health by 3%.","While in Bear Form, increases your attack power by 8% and maximum health by 4%.","While in Bear Form, increases your attack power by 10% and maximum health by 5%."},
[919300]={"Taking direct damage while Ironfur is active heals you for 1% of maximum health. Cannot occur more than once every 3 sec; only triggers if you survive the hit and cannot trigger itself.","Taking direct damage while Ironfur is active heals you for 2% of maximum health. Cannot occur more than once every 3 sec; only triggers if you survive the hit and cannot trigger itself."},
[919310]={"Survival Instincts and Frenzied Regeneration each activate Ironfur for 6 sec without spending Rage. Pulverize consuming at least 3 Lacerate stacks extends active Ironfur by 2 sec, at most once every 6 sec and never beyond its full talented duration. While Ironfur is active, Savage Defense absorbs 20% more damage. Free Ironfur refreshes rather than stacks its armor bonus."},
}
